package com.esn.smp.gameplay;
import org.bukkit.*;import org.bukkit.attribute.Attribute;import org.bukkit.entity.*;import org.bukkit.event.*;import org.bukkit.event.entity.*;import org.bukkit.event.player.*;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.persistence.*;import org.bukkit.plugin.java.JavaPlugin;import java.util.*;import java.util.concurrent.*;
public final class EndgameSystems implements Listener{
 private final JavaPlugin p;private final NamespacedKey artifact,pet,gear;private final Map<UUID,Integer> bossKills=new HashMap<>(),pity=new HashMap<>();private final Map<UUID,Set<UUID>> participants=new ConcurrentHashMap<>();private final Map<UUID,Long> artifactCooldown=new ConcurrentHashMap<>();
 public EndgameSystems(JavaPlugin p){this.p=p;artifact=new NamespacedKey(p,"artifact");pet=new NamespacedKey(p,"boss_pet");gear=new NamespacedKey(p,"biome_set");Bukkit.getScheduler().runTaskTimer(p,this::worldPulse,1200L,72000L);Bukkit.getScheduler().runTaskTimer(p,this::diagnostics,100L,12000L);}
 private void diagnostics(){if(MegaCrates.COUNT!=100||MegaCrates.ITEMS<10)p.getLogger().severe("DIAGNOSTIC: Realm crate definition mismatch.");else p.getLogger().info("ESN diagnostics OK: 100 Realm crates, biome/endgame systems active.");}
 private String rarity(){double r=ThreadLocalRandom.current().nextDouble();return r<.01?"CATACLYSM":r<.04?"NIGHTMARE":r<.10?"MYTHIC":r<.25?"ELITE":"NORMAL";}
 private double rarityMult(String r){return switch(r){case"CATACLYSM"->2.2;case"NIGHTMARE"->1.9;case"MYTHIC"->1.55;case"ELITE"->1.25;default->1;};}
 @EventHandler public void bossSpawn(CreatureSpawnEvent e){LivingEntity z=e.getEntity();Bukkit.getScheduler().runTask(p,()->{if(!z.isValid()||(!z.getScoreboardTags().contains("esnBiomeBoss")&&!z.getScoreboardTags().contains("esnWorldBoss")&&!z.getScoreboardTags().contains("esnSwampBoss")))return;String r=rarity();z.addScoreboardTag("esnRarity_"+r);var max=z.getAttribute(Attribute.MAX_HEALTH);if(max!=null){double base=z.getScoreboardTags().contains("esnWorldBoss")?100000.0:50000.0;double hp=base*rarityMult(r);max.setBaseValue(hp);z.setHealth(hp);}if(!r.equals("NORMAL"))z.setCustomName(ChatColor.GOLD+"["+r+"] "+(z.getCustomName()==null?"ESN BOSS":z.getCustomName()));});}
 @EventHandler public void hit(EntityDamageByEntityEvent e){if(!(e.getEntity() instanceof LivingEntity z)||(!z.getScoreboardTags().contains("esnBiomeBoss")&&!z.getScoreboardTags().contains("esnWorldBoss")&&!z.getScoreboardTags().contains("esnSwampBoss")))return;Player x=e.getDamager() instanceof Player q?q:e.getDamager() instanceof Projectile pr&&pr.getShooter() instanceof Player q?q:null;if(x!=null){participants.computeIfAbsent(z.getUniqueId(),q->ConcurrentHashMap.newKeySet()).add(x.getUniqueId());int nearby=(int)z.getWorld().getPlayers().stream().filter(a->a.getLocation().distanceSquared(z.getLocation())<2500).count();var max=z.getAttribute(Attribute.MAX_HEALTH);if(max!=null&&!z.getScoreboardTags().contains("esnScaled")){double hp=max.getBaseValue()*(1+Math.max(0,nearby-1)*.18);max.setBaseValue(hp);z.setHealth(hp);z.addScoreboardTag("esnScaled");}}}
 @EventHandler public void phase(EntityDamageEvent e){if(!(e.getEntity() instanceof LivingEntity z)||(!z.getScoreboardTags().contains("esnBiomeBoss")&&!z.getScoreboardTags().contains("esnWorldBoss")&&!z.getScoreboardTags().contains("esnSwampBoss")))return;var max=z.getAttribute(Attribute.MAX_HEALTH);if(max==null)return;double after=z.getHealth()-e.getFinalDamage(),pct=after/max.getValue();String tag=pct<.25?"esnPhase3":pct<.50?"esnPhase2":pct<.75?"esnPhase1":null;if(tag!=null&&!z.getScoreboardTags().contains(tag)){z.addScoreboardTag(tag);z.getWorld().spawnParticle(Particle.EXPLOSION,z.getLocation().add(0,1,0),8);for(Entity q:z.getNearbyEntities(5,3,5))if(q instanceof Player x){x.damage(4,z);x.setVelocity(x.getLocation().toVector().subtract(z.getLocation().toVector()).normalize().multiply(1.2));}z.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.STRENGTH,200,Math.min(3,tag.charAt(tag.length()-1)-'0')));}}
 @EventHandler public void bossDeath(EntityDeathEvent e){LivingEntity z=e.getEntity();if(!z.getScoreboardTags().contains("esnBiomeBoss")&&!z.getScoreboardTags().contains("esnWorldBoss")&&!z.getScoreboardTags().contains("esnSwampBoss"))return;Player k=z.getKiller();if(k==null)return;int n=bossKills.merge(k.getUniqueId(),1,Integer::sum),miss=pity.merge(k.getUniqueId(),1,Integer::sum);if(n%10==0)k.sendMessage(ChatColor.GOLD+"Boss Mastery "+n+" — new milestone reached!");double rare=Math.min(.30,.03+miss*.005);if(ThreadLocalRandom.current().nextDouble()<rare){ItemStack a=artifact();e.getDrops().add(a);pity.put(k.getUniqueId(),0);Bukkit.broadcastMessage(ChatColor.LIGHT_PURPLE+k.getName()+" discovered a MYTHIC BOSS ARTIFACT!");k.sendTitle(ChatColor.LIGHT_PURPLE+"✦ MYTHIC DROP ✦",ChatColor.GOLD+"Boss Artifact",10,60,20);k.playSound(k.getLocation(),Sound.UI_TOAST_CHALLENGE_COMPLETE,1f,1.2f);k.getWorld().spawnParticle(Particle.END_ROD,k.getLocation().add(0,1,0),70,1,1,1,.06);}if(ThreadLocalRandom.current().nextDouble()<.01)e.getDrops().add(pet());if(ThreadLocalRandom.current().nextDouble()<.18)e.getDrops().add(setPiece(z));for(UUID id:new HashSet<>(participants.getOrDefault(z.getUniqueId(),Set.of()))){Player x=Bukkit.getPlayer(id);if(x!=null&&x.getWorld()==z.getWorld()&&x.getLocation().distanceSquared(z.getLocation())<6400){x.giveExp(75);x.sendActionBar(ChatColor.GOLD+"Boss participation: +75 XP");}}participants.remove(z.getUniqueId());}
 private ItemStack setPiece(LivingEntity z){String fam=z.getScoreboardTags().stream().filter(a->a.startsWith("esnBiome_")).findFirst().orElse("esnBiome_REALM").substring(9);Material[] ms={Material.NETHERITE_HELMET,Material.NETHERITE_CHESTPLATE,Material.NETHERITE_LEGGINGS,Material.NETHERITE_BOOTS};Material m=ms[ThreadLocalRandom.current().nextInt(ms.length)];ItemStack i=new ItemStack(m);ItemMeta im=i.getItemMeta();im.setDisplayName(ChatColor.GOLD+fam+" Boss Set "+m.name().substring(m.name().indexOf('_')+1));im.setLore(List.of(ChatColor.LIGHT_PURPLE+"Biome Set: "+fam,ChatColor.GRAY+"Wear multiple pieces for escalating combat bonuses."));im.getPersistentDataContainer().set(gear,PersistentDataType.STRING,fam);im.addEnchant(org.bukkit.enchantments.Enchantment.PROTECTION,25,true);im.addEnchant(org.bukkit.enchantments.Enchantment.UNBREAKING,25,true);i.setItemMeta(im);return i;}
 @EventHandler public void setBonus(PlayerMoveEvent e){if(e.getFrom().getBlockX()==e.getTo().getBlockX()&&e.getFrom().getBlockZ()==e.getTo().getBlockZ())return;Player x=e.getPlayer();Map<String,Integer> n=new HashMap<>();for(ItemStack i:x.getInventory().getArmorContents())if(i!=null&&i.hasItemMeta()){String f=i.getItemMeta().getPersistentDataContainer().get(gear,PersistentDataType.STRING);if(f!=null)n.merge(f,1,Integer::sum);}int best=n.values().stream().mapToInt(Integer::intValue).max().orElse(0);if(best>=2)x.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.SPEED,60,0,true,false));if(best>=3)x.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.RESISTANCE,60,0,true,false));if(best>=4)x.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.STRENGTH,60,0,true,false));}
 private ItemStack artifact(){ItemStack i=new ItemStack(Material.NETHER_STAR);ItemMeta m=i.getItemMeta();m.setDisplayName(ChatColor.LIGHT_PURPLE+"Mythic Boss Artifact");m.setLore(List.of(ChatColor.GRAY+"Rare ability relic",ChatColor.GOLD+"Right-click: temporary Strength + Resistance"));m.getPersistentDataContainer().set(artifact,PersistentDataType.BYTE,(byte)1);i.setItemMeta(m);return i;}
 private ItemStack pet(){ItemStack i=new ItemStack(Material.ALLAY_SPAWN_EGG);ItemMeta m=i.getItemMeta();m.setDisplayName(ChatColor.AQUA+"Boss Spirit Pet");m.setLore(List.of(ChatColor.GRAY+"Ultra-rare boss collectible"));m.getPersistentDataContainer().set(pet,PersistentDataType.BYTE,(byte)1);i.setItemMeta(m);return i;}
 @EventHandler public void use(PlayerInteractEvent e){ItemStack i=e.getItem();if(i==null||!i.hasItemMeta()||!i.getItemMeta().getPersistentDataContainer().has(artifact,PersistentDataType.BYTE))return;Player x=e.getPlayer();long now=System.currentTimeMillis();if(artifactCooldown.getOrDefault(x.getUniqueId(),0L)>now){x.sendActionBar(ChatColor.RED+"Artifact recharging");return;}artifactCooldown.put(x.getUniqueId(),now+30000);x.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.STRENGTH,200,2));x.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.RESISTANCE,200,1));x.sendActionBar(ChatColor.LIGHT_PURPLE+"Artifact power awakened");}
 private void worldPulse(){if(Bukkit.getOnlinePlayers().isEmpty())return;int r=ThreadLocalRandom.current().nextInt(4);String[] msg={"A Blood Moon surge empowers hostile creatures!","A meteor signal has appeared somewhere in the overworld!","Realm instability is strengthening regional bosses!","Treasure hunters report ancient caches awakening!"};Bukkit.broadcastMessage(ChatColor.DARK_RED+"[WORLD EVENT] "+ChatColor.GOLD+msg[r]);for(World w:Bukkit.getWorlds())if(w.getEnvironment()==World.Environment.NORMAL&&r==0)for(LivingEntity e:w.getLivingEntities())if(e instanceof Monster){e.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.STRENGTH,2400,1));e.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.SPEED,2400,0));}}
}